class Terrain {
  constructor(manager) {
    this.m = manager;

    const { terrainSize } = this.m.params;
    this.size = terrainSize;
    this.area = terrainSize * terrainSize;

    this.heightMap         = new Float32Array(this.area);
    this.originalHeightMap = new Float32Array(this.area);
    this.bedrockMap        = new Float32Array(this.area);
    this.sedimentMap       = new Float32Array(this.area);
    this.dischargeMap      = new Float32Array(this.area);
    this.dischargeTrack    = new Float32Array(this.area);
    this.momentumX         = new Float32Array(this.area);
    this.momentumY         = new Float32Array(this.area);
    this.momentumXTrack    = new Float32Array(this.area);
    this.momentumYTrack    = new Float32Array(this.area);

    this.sharedNormal = { x: 0, y: 0, z: 0 };
  }

  getIndex(x, y) {
    return y * this.size + x;
  }

  getHeight(x, y) {
    const { size, heightMap } = this;
    if (x < 0 || x >= size || y < 0 || y >= size) return 0;
    return heightMap[y * size + x];
  }

  updateTotalHeight(index) {
    this.heightMap[index] = this.bedrockMap[index] + this.sedimentMap[index];
  }

  getMapBounds(mapArray) {
    let minVal = Infinity;
    let maxVal = -Infinity;

    for (let i = 0; i < mapArray.length; i++) {
      const val = mapArray[i];
      if (val < minVal) minVal = val;
      if (val > maxVal) maxVal = val;
    }

    return { min: minVal, max: maxVal };
  }

  getSurfaceNormal(x, y) {
    const { size, heightMap, sharedNormal } = this;
    const { heightScale } = this.m.params;

    const west  = x > 0 ? y * size + (x - 1) : y * size + x;
    const east  = x < size - 1 ? y * size + (x + 1) : y * size + x;
    const north = y > 0 ? (y - 1) * size + x : y * size + x;
    const south = y < size - 1 ? (y + 1) * size + x : y * size + x;

    const deltaX = (heightMap[west] - heightMap[east]) * heightScale;
    const deltaZ = (heightMap[north] - heightMap[south]) * heightScale;
    const deltaY = 1.0;

    const mag = Math.sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);

    sharedNormal.x = deltaX / mag;
    sharedNormal.y = deltaY / mag;
    sharedNormal.z = deltaZ / mag;

    return sharedNormal;
  }

  getDischarge(index) {
    return this.codyErf(0.4 * this.dischargeMap[index]);
  }

  codyErf(x) {
    const absX = Math.abs(x);
    if (absX > 9.3) return x > 0 ? 1.0 : -1.0;

    let result;
    if (absX <= 0.84375) {
      const xSq = x * x;
      const p = [3.1611237438705656, 113.86415415105016, 377.485237685302, 3209.3775891384695, 0.18577770618460315];
      const q = [23.601290953873412, 244.55303442692948, 1287.1751860847748, 2844.2368334391706];

      const num = (((p[4] * xSq + p[0]) * xSq + p[1]) * xSq + p[2]) * xSq + p[3];
      const den = (((xSq + q[0]) * xSq + q[1]) * xSq + q[2]) * xSq + q[3];
      result = x * (num / den);
    } else if (absX <= 4.0) {
      const p = [0.5641884969886701, 8.883149794388376, 66.11542093743808, 298.63513819740013, 881.9522212417691, 1712.0476126340706, 2051.0783778260715, 1230.3393547979972, 2.1531153547440385e-8];
      const q = [15.744926110709835, 117.6939508913125, 537.1811018620099, 1621.3895745386784, 3290.7992357334596, 4362.61909014206, 3439.3676741437216, 1230.3393548037443];

      const n = (((((((p[8] * absX + p[0]) * absX + p[1]) * absX + p[2]) * absX + p[3]) * absX + p[4]) * absX + p[5]) * absX + p[6]) * absX + p[7];
      const d = (((((((absX + q[0]) * absX + q[1]) * absX + q[2]) * absX + q[3]) * absX + q[4]) * absX + q[5]) * absX + q[6]) * absX + q[7];

      result = 1.0 - Math.exp(-x * x) * (n / d);
      if (x < 0) result = -result;
    } else {
      result = x > 0 ? 1.0 : -1.0;
    }
    return result;
  }

  generate() {
    const { noiseScale, noiseOctaves, amplitudeFalloff } = this.m.params;
    const { size, area, heightMap, originalHeightMap, bedrockMap } = this;

    this.reset();

    const offsets = Array.from({ length: noiseOctaves }, () => ({
      x: random(100000), 
      y: random(100000)
    }));

    for (let i = 0; i < area; i++) {
      const x = i % size;
      const y = (i / size) | 0;

      let amp = 1;
      let freq = noiseScale / 100;
      let noiseVal = 0;

      for (let o = 0; o < noiseOctaves; o++) {
        const sx = x * freq + offsets[o].x;
        const sy = y * freq + offsets[o].y;
        noiseVal += noise(sx, sy) * amp;
        freq *= 2;
        amp *= amplitudeFalloff;
      }
      heightMap[i] = Math.pow(noiseVal, 1.2);
    }

    const { min, max } = this.getMapBounds(heightMap);
    const range = max - min || 1;

    for (let i = 0; i < area; i++) {
      const norm = (heightMap[i] - min) / range;
      heightMap[i] = norm;
      bedrockMap[i] = norm;
      originalHeightMap[i] = norm;
    }
  }

  reset() {
    const { 
      heightMap, bedrockMap, originalHeightMap, sedimentMap, 
      dischargeMap, dischargeTrack, momentumX, momentumY, 
      momentumXTrack, momentumYTrack 
    } = this;

    [heightMap, bedrockMap].forEach(m => m.set(originalHeightMap));

    [
      sedimentMap, dischargeMap, dischargeTrack, 
      momentumX, momentumY, momentumXTrack, momentumYTrack
    ].forEach(m => m.fill(0));
  }
}

// === Tab: Solver.js ===
class Solver {
  constructor(manager) {
    this.m = manager;

    const SQRT2 = Math.SQRT2;
    this.neighbours = [
      { x: -1, y: -1, distance: SQRT2 }, { x: -1, y: 0, distance: 1 }, { x: -1, y: 1, distance: SQRT2 },
      { x: 0, y: -1, distance: 1 },                                   { x: 0, y: 1, distance: 1 },
      { x: 1, y: -1, distance: SQRT2 },  { x: 1, y: 0, distance: 1 },  { x: 1, y: 1, distance: SQRT2 },
    ];
  }

  updateDischargeMap() {
    const { learningRate } = this.m.params;
    const { 
      area, dischargeMap, dischargeTrack, 
      momentumX, momentumXTrack, momentumY, momentumYTrack 
    } = this.m.terrain;

    const invLR = 1.0 - learningRate;

    for (let i = 0; i < area; i++) {
      dischargeMap[i] = invLR * dischargeMap[i] + learningRate * dischargeTrack[i];
      momentumX[i]    = invLR * momentumX[i]    + learningRate * momentumXTrack[i];
      momentumY[i]    = invLR * momentumY[i]    + learningRate * momentumYTrack[i];
    }
  }

  hydraulicErosion() {
    const {
      dropletsPerFrame, maxAge, minVolume, precipitationRate,
      gravity, momentumTransfer, entrainment, depositionRate,
      evaporationRate, sedimentErosionRate, bedrockErosionRate
    } = this.m.params;

    const { terrain } = this.m;
    const { 
      size, heightMap, sedimentMap, bedrockMap, 
      dischargeTrack, momentumXTrack, momentumYTrack,
      momentumX, momentumY, dischargeMap
    } = terrain;

    dischargeTrack.fill(0);
    momentumXTrack.fill(0);
    momentumYTrack.fill(0);

    for (let d = 0; d < dropletsPerFrame; d++) {
      let x = random(size) | 0;
      let y = random(size) | 0;

      if (terrain.getHeight(x, y) < 0.1) continue;

      let vx = 0, vy = 0, sediment = 0, age = 0;
      let volume = precipitationRate;

      let _wG_1 = 0; while ((age < maxAge && volume >= minVolume) && ++_wG_1 < 20000) {
        const floorX = x | 0;
        const floorY = y | 0;

        if (floorX < 0 || floorX >= size || floorY < 0 || floorY >= size) break;

        const index = terrain.getIndex(floorX, floorY);
        const heightStart = heightMap[index];
        const normal = terrain.getSurfaceNormal(floorX, floorY);

        vx += (gravity * normal.x) / volume;
        vy += (gravity * normal.z) / volume;

        const pmX = momentumX[index];
        const pmY = momentumY[index];
        const pmMag = Math.sqrt(pmX * pmX + pmY * pmY);

        if (pmMag > 0) {
          const speed = Math.sqrt(vx * vx + vy * vy);
          if (speed > 0) {
            const alignment = (pmX * vx + pmY * vy) / (pmMag * speed);
            const transfer = (momentumTransfer * alignment) / (volume + dischargeMap[index]);
            vx += transfer * pmX;
            vy += transfer * pmY;
          }
        }

        const finalSpeed = Math.sqrt(vx * vx + vy * vy);
        if (finalSpeed > 0) {
          const mag = Math.SQRT2 / finalSpeed;
          vx *= mag; vy *= mag;
        }

        x += vx; y += vy;

        dischargeTrack[index] += volume;
        momentumXTrack[index] += volume * vx;
        momentumYTrack[index] += volume * vy;

        const isOut = (x < 0 || x >= size || y < 0 || y >= size);
        const heightEnd = isOut ? heightStart - 0.002 : terrain.getHeight(x | 0, y | 0);

        const transportCapacity = Math.max(0, (1 + entrainment * terrain.getDischarge(index)) * (heightStart - heightEnd));
        const deficit = transportCapacity - sediment;

        if (deficit > 0) {
          const fromSed = Math.min(sedimentMap[index], deficit * sedimentErosionRate);
          sedimentMap[index] -= fromSed;

          let actualEroded = fromSed;
          const remainingDeficit = deficit - (fromSed / sedimentErosionRate);

          if (remainingDeficit > 0) {
            const fromBed = remainingDeficit * bedrockErosionRate;
            bedrockMap[index] -= fromBed;
            actualEroded += fromBed;
          }
          sediment += actualEroded;
        } else {
          const dep = -deficit * depositionRate;
          sedimentMap[index] += dep;
          sediment -= dep;
        }

        terrain.updateTotalHeight(index);

        const evap = (1 - evaporationRate);
        volume *= evap;
        sediment *= evap;

        if (isOut) break;

        this.thermalErosion(x, y);
        age++;
      }
    }
  }

  thermalErosion(x, y) {
    const { terrain } = this.m;
    const { size, heightMap, sedimentMap, bedrockMap } = terrain;
    const { maxHeightDiff, settlingRate } = this.m.params;

    const cx = x | 0;
    const cy = y | 0;

    if (cx < 0 || cx >= size || cy < 0 || cy >= size) return;

    const cIdx = terrain.getIndex(cx, cy);
    const cHeight = heightMap[cIdx];

    for (let i = 0; i < this.neighbours.length; i++) {
      const { x: nxOff, y: nyOff, distance } = this.neighbours[i];
      const nx = cx + nxOff;
      const ny = cy + nyOff;

      if (nx < 0 || nx >= size || ny < 0 || ny >= size) continue;

      const nIdx = terrain.getIndex(nx, ny);
      const nHeight = heightMap[nIdx];
      const diff = cHeight - nHeight;

      if (diff === 0) continue;

      const excess = Math.abs(diff) - distance * maxHeightDiff;
      if (excess <= 0) continue;

      const transfer = (settlingRate * excess) / 2;
      const srcIdx = diff > 0 ? cIdx : nIdx;
      const tgtIdx = diff > 0 ? nIdx : cIdx;

      heightMap[srcIdx] -= transfer;
      heightMap[tgtIdx] += transfer;

      let remaining = transfer;
      const fromSed = Math.min(remaining, sedimentMap[srcIdx]);

      sedimentMap[srcIdx] -= fromSed;
      remaining -= fromSed;

      if (remaining > 0) {
        bedrockMap[srcIdx] -= remaining;
      }
      sedimentMap[tgtIdx] += transfer;
    }
  }
}

// === Tab: Camera.js ===
class Camera {
  constructor(manager) {
    this.m = manager;

    this.target = {
      yaw: 0,
      pitch: 0.8,
      zoom: 750
    };

    this.current = {
      yaw: 0,
      pitch: 0.8,
      zoom: 750
    };

    this.quaternion = new Quaternion();

    this.gesture = {
      orbit: null,
      pinch: null
    };

    this.lerpWeight = 0.25;
  }

  update() {
    const { current, target, lerpWeight } = this;

    current.yaw   = lerp(current.yaw,   target.yaw,   lerpWeight);
    current.pitch = lerp(current.pitch, target.pitch, lerpWeight);
    current.zoom  = lerp(current.zoom,  target.zoom,  lerpWeight);

    this.quaternion = Quaternion.fromEuler(current.pitch, current.yaw).normalise();
  }

  getEyePosition() {
    const { zoom } = this.current;
    return this.quaternion.applyToVector({ x: 0, y: zoom, z: 0 });
  }

  getUpVector() {
    return this.quaternion.applyToVector({ x: 0, y: 0, z: -1 });
  }

  getViewDirection() {
    return this.quaternion.applyToVector({ x: 0, y: 1, z: 0 });
  }

  handleWheel(e) {
    this.target.zoom = max(20, this.target.zoom + e.delta * 0.5);
  }

  handlePointer() {
    let points = touches.length > 0 ? touches : [];
    if (points.length === 0 && ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
      points = [{ x: (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), y: (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) }];
    }

    const count = points.length;

    if (count === 1) {
      this.handleOrbit(points[0]);
    } else if (count === 2) {
      this.handlePinch(points[0], points[1]);
    } else {
      const { gesture } = this;
      gesture.orbit = null;
      gesture.pinch = null;
    }
  }

  handleOrbit(touch) {
    const { gesture, target } = this;

    if (!gesture.orbit) {
      gesture.orbit = { x: touch.x, y: touch.y };
      gesture.pinch = null;
      return;
    }

    const dx = (touch.x - gesture.orbit.x) * 0.007;
    const dy = (touch.y - gesture.orbit.y) * 0.007;

    target.yaw += dx;
    target.pitch = constrain(target.pitch + dy, -1.56, 1.56);

    gesture.orbit.x = touch.x;
    gesture.orbit.y = touch.y;
  }

  handlePinch(t1, t2) {
    const { gesture, target } = this;
    const distance = dist(t1.x, t1.y, t2.x, t2.y);

    if (!gesture.pinch) {
      gesture.pinch = { distance };
      gesture.orbit = null;
      return;
    }

    const ratio = distance / gesture.pinch.distance;
    target.zoom = max(20, target.zoom / ratio);

    gesture.pinch.distance = distance;
  }
}

// === Tab: Renderer.js ===
class Renderer {
  constructor(manager) {
    this.m = manager;

    this.canvas3D = createGraphics(width, height, WEBGL);
    this.terrainShader = this.canvas3D.createShader(
      this.m.shaders.vert,
      this.m.shaders.frag
    );

    const { size } = this.m.terrain;
    this.canvas2D = createImage(size, size);
    this.heightMapTexture = createImage(size, size);

    this.lut = new Uint8ClampedArray(256 * 3);
    this.currentColourMap = "";
  }

  reinitialise() {
    const { size } = this.m.terrain;
    this.canvas2D = createImage(size, size);
    this.heightMapTexture = createImage(size, size);
  }

  updateLUT(colourMap) {
    if (this.currentColourMap === colourMap) return;

    const colourData = this.m.colourMaps[colourMap];
    if (!colourData) return;

    this.currentColourMap = colourMap;
    const channels = ["r", "g", "b"];

    for (let i = 0; i < 256; i++) {
      const intensity = i / 255;

      for (let c = 0; c < 3; c++) {
        const coeffs = colourData[channels[c]];
        let val = 0;

        for (let j = coeffs.length - 1; j >= 0; j--) {
          val = val * intensity + coeffs[j];
        }

        this.lut[i * 3 + c] = constrain(val * 255, 0, 255);
      }
    }
  }

  generateTextures(is3D) {
    const { params, terrain, camera, statistics } = this.m;
    const { 
      surfaceMap, lightDir, flatColour, steepColour, 
      sedimentColour, waterColour, skyColour, specularIntensity 
    } = params;

    const { size, area, heightMap, originalHeightMap, sedimentMap, dischargeMap } = terrain;

    if (surfaceMap !== "composite") {
      this.updateLUT(params.colourMap || "viridis");
    }

    const lightMag = Math.sqrt(lightDir.x ** 2 + lightDir.y ** 2 + lightDir.z ** 2) || 1;
    const lX = lightDir.x / lightMag;
    const lY = lightDir.y / lightMag;
    const lZ = lightDir.z / lightMag;

    let vX = 0, vY = 1, vZ = 0;
    if (is3D) {
      const v = camera.getViewDirection();
      vX = v.x; vY = v.y; vZ = v.z;
    }

    const bounds = this.calculateBounds(surfaceMap);

    this.canvas2D.loadPixels();
    this.heightMapTexture.loadPixels();

    for (let i = 0; i < area; i++) {
      const idx = i << 2;
      const hVal = heightMap[i];

      const hByte = (hVal * 255) | 0;
      this.heightMapTexture.pixels[idx] = hByte;
      this.heightMapTexture.pixels[idx + 1] = hByte;
      this.heightMapTexture.pixels[idx + 2] = hByte;
      this.heightMapTexture.pixels[idx + 3] = 255;

      let r, g, b;

      if (surfaceMap === "composite") {
        const x = i % size;
        const y = (i / size) | 0;
        const normal = terrain.getSurfaceNormal(x, y);

        const dot = normal.x * lX + normal.y * lY + normal.z * lZ;
        const diffuse = Math.max(0, dot);
        const sW = normal.y * 0.5 + 0.5;

        const shR = diffuse + (skyColour.r * 0.000588) * sW;
        const shG = diffuse + (skyColour.g * 0.000588) * sW;
        const shB = diffuse + (skyColour.b * 0.000588) * sW;

        const steep = 1 - normal.y;
        r = (normal.y * flatColour.r + steep * steepColour.r) * shR;
        g = (normal.y * flatColour.g + steep * steepColour.g) * shG;
        b = (normal.y * flatColour.b + steep * steepColour.b) * shB;

        const sed = sedimentMap[i];
        if (sed > 0) {
          const a = Math.min(1, sed * 5);
          r = (1 - a) * r + a * sedimentColour.r * shR;
          g = (1 - a) * g + a * sedimentColour.g * shG;
          b = (1 - a) * b + a * sedimentColour.b * shB;
        }

        const dis = terrain.getDischarge(i);
        if (dis > 0) {
          const a = Math.min(1, dis);
          const s = Math.max(0.3, 1 - dis * 0.25);

          r = (1 - a) * r + a * waterColour.r * s * shR;
          g = (1 - a) * g + a * waterColour.g * s * shG;
          b = (1 - a) * b + a * waterColour.b * s * shB;

          if (is3D) {
            const hX = lX + vX, hY = lY + vY, hZ = lZ + vZ;
            const hM = Math.sqrt(hX * hX + hY * hY + hZ * hZ) || 1;
            const ndotH = Math.max(0, (normal.x * hX + normal.y * hY + normal.z * hZ) / hM);
            const spec = Math.pow(ndotH, 120) * (specularIntensity || 255) * a;

            r = Math.min(255, r + spec);
            g = Math.min(255, g + spec);
            b = Math.min(255, b + spec);
          }
        }
      } else {
        let v = 0;
        if (surfaceMap === "height") {
          v = (hVal - bounds.min) / bounds.range;
        } else if (surfaceMap === "slope") {
          v = 1 - terrain.getSurfaceNormal(i % size, (i / size) | 0).y;
        } else if (surfaceMap === "discharge") {
          v = terrain.getDischarge(i);
        } else if (surfaceMap === "sediment") {
          v = (sedimentMap[i] - bounds.min) / bounds.range;
        } else if (surfaceMap === "delta") {
          v = 0.5 + (hVal - originalHeightMap[i]) * 10;
        }

        const lIdx = constrain((v * 255) | 0, 0, 255) * 3;
        r = this.lut[lIdx];
        g = this.lut[lIdx + 1];
        b = this.lut[lIdx + 2];
      }

      this.canvas2D.pixels[idx] = r;
      this.canvas2D.pixels[idx + 1] = g;
      this.canvas2D.pixels[idx + 2] = b;
      this.canvas2D.pixels[idx + 3] = 255;
    }

    this.canvas2D.updatePixels();
    this.heightMapTexture.updatePixels();
  }

  calculateBounds(mode) {
    const { statistics } = this.m;

    if (mode === "height") {
      const { min, max } = statistics.heightBounds;
      return { min, range: (max - min) || 1 };
    }

    if (mode === "discharge") {
      return { min: 0, range: statistics.peakDischarge || 1 };
    }

    if (mode === "sediment") {
      const { min, max } = statistics.sedimentBounds;
      return { min, range: (max - min) || 1 };
    }

    return { min: 0, range: 1 };
  }

  render() {
    const is3D = (this.m.params.displayMethod === "3D");

    this.generateTextures(is3D);

    if (is3D) {
      this.render3D();
    } else {
      this.render2D();
    }

	 this.renderOverlay();
  }

  render2D() {
    image(this.canvas2D, 0, 0, width, height);
  }

  render3D() {
    const { canvas3D, terrainShader, heightMapTexture, canvas2D } = this;
    const { terrain, params, camera } = this.m;
    const eye = camera.getEyePosition();
    const up = camera.getUpVector();

    canvas3D.background(params.skyColour.r, params.skyColour.g, params.skyColour.b);

    canvas3D.push();
    canvas3D.resetMatrix();
    canvas3D.perspective(PI / 3, width / height, 0.1, 30000);
    canvas3D.camera(eye.x, eye.y, eye.z, 0, 0, 0, up.x, up.y, up.z);

	 canvas3D.noStroke();
    canvas3D.shader(terrainShader);
    terrainShader.setUniform("uHeightMap", heightMapTexture);
    terrainShader.setUniform("uTexture", canvas2D);
    terrainShader.setUniform("uHeightScale", params.heightScale);

    const pSize = terrain.size * 2;
    canvas3D.plane(pSize, pSize, terrain.size - 1, terrain.size - 1);
    canvas3D.pop();

    image(canvas3D, 0, 0, width, height);
  }

  renderOverlay() {
    if (this.m.params.renderStats) this.renderStats();
    if (this.m.params.renderLegend) this.renderLegend();
  }

  renderStats() {
    push();
    const { statistics, params } = this.m;

    fill(255);
    textSize(15);
    textAlign(LEFT, TOP);

    const lines = [
      `FPS: ${statistics.fps.toFixed(2)}`,
      `Time: ${statistics.simulationTime.toFixed(2)}s`,
	   `Display Method: ${params.displayMethod}`,
      `Surface Map: ${params.surfaceMap}`,
	   `Colour Map: ${params.colourMap}`,
      `Elevation Range: ${statistics.minElevation.toFixed(3)} - ${statistics.maxElevation.toFixed(3)}`,
      `Peak Discharge: ${statistics.peakDischarge.toFixed(3)}`,
      `Rugosity Index: ${statistics.rugosity.toFixed(3)}`
    ];

    text(lines.join('\n'), 20, 20);
    pop();
  }

  renderLegend() {
    if (this.m.params.surfaceMap === "composite") {
      this.renderCompositeLegend();
    } else {
      this.renderDataLegend();
    }
  }

  renderCompositeLegend() {
    push();
    const { flatColour, steepColour, sedimentColour, waterColour } = this.m.params;

    const items = [
      { l: "Flat", c: flatColour },
      { l: "Steep", c: steepColour },
      { l: "Sediment", c: sedimentColour },
      { l: "Water", c: waterColour }
    ];

    textSize(14);
    textAlign(LEFT, CENTER);

    items.forEach((item, i) => {
      const y = 15 + i * 28;
      fill(item.c.r, item.c.g, item.c.b);
		stroke(255, 200);
		strokeWeight(1);
      rect(width - 110, y, 20, 20);

      fill(255);
		noStroke();
      text(item.l, width - 82, y + 10);
    });
    pop();
  }

  renderDataLegend() {
    push();
    const { surfaceMap, colourMap } = this.m.params;
    this.updateLUT(colourMap || "viridis");

    const x = width - 15;
    const y1 = 15;
    const y2 = height - 15;
    const w = 20;
    const h = y2 - y1;

    const grad = drawingContext.createLinearGradient(0, y1, 0, y2);
    for (let i = 0; i <= 10; i++) {
      const t = i / 10;
      const idx = (((1 - t) * 255) | 0) * 3;
      grad.addColorStop(t, `rgb(${this.lut[idx]}, ${this.lut[idx+1]}, ${this.lut[idx+2]})`);
    }

	 drawingContext.strokeStyle = 'rgba(255, 255, 255, 0.78)';
    drawingContext.lineWidth = 1;

    drawingContext.fillStyle = grad;
    drawingContext.fillRect(x - w, y1, w, h);

    drawingContext.strokeRect(x - w, y1, w, h);

    const b = this.calculateBounds(surfaceMap);
    const labels = [
      { v: b.min + b.range, y: y1 },
      { v: b.min + b.range / 2, y: y1 + h / 2 },
      { v: b.min, y: y2 }
    ];

    fill(255);
    textSize(11);
    textAlign(RIGHT, CENTER);

    labels.forEach(l => {
      text(l.v.toFixed(3), x - w - 6, l.y);
      stroke(255, 100);
      line(x - w - 3, l.y, x - w, l.y);
    });
    pop();
  }

  resize() {
    const s = max(windowWidth, windowHeight);
    if (this.canvas3D) {
      this.canvas3D.resizeCanvas(s, s);
    }
  }
}

// === Tab: Analyser.js ===
class Analyser {
  constructor(manager) {
    this.m = manager;
    this.simulationStartTime = performance.now();
    this.reinitialise();
  }

  reinitialise() {
    const { area } = this.m.terrain;
    const stats = this.m.statistics;

    this.simulationStartTime = performance.now();
    this.lastAnalysisTime = performance.now();
    this.prevTotalSediment = 0;
    this.prevTotalBedrock = 0;

    stats.simulationTime = 0;
    stats.frameCounter = 0;
    stats.heightHistogram = new Int32Array(256);
    stats.normHistogram = new Float32Array(256);

    stats.rugosity = 0;
    stats.drainageDensity = 0;
    stats.sedimentFlux = 0;
    stats.erosionRate = 0;
    stats.hydraulicResidence = 0;

    stats.totalWater = 0;
    stats.totalSediment = 0;
    stats.totalBedrock = 0;

    stats.maxElevation = 0;
    stats.minElevation = 0;
    stats.avgElevation = 0;
    stats.elevationStdDev = 0;

    stats.peakDischarge = 0;
    stats.activeWaterCover = 0;
    stats.slopeComplexity = 0;

    stats.heightBounds = { min: 0, max: 0 };
    stats.sedimentBounds = { min: 0, max: 0 };
    stats.dischargeBounds = { min: 0, max: 0 };
  }

  update() {
    const { statistics, params } = this.m;
    statistics.fps = frameRate();
    statistics.frameCounter++;
    statistics.simulationTime = (performance.now() - this.simulationStartTime) / 1000;

    if (params.running) {
      this.runAnalysis();
    }
  }

  runAnalysis() {
    const { terrain, statistics, params } = this.m;
    const { area, size, heightMap, bedrockMap, sedimentMap, dischargeMap } = terrain;
    const { heightScale, evaporationRate } = params;

    let totalW = 0, totalS = 0, totalB = 0, riverCells = 0, totalSA = 0;
    let minE = Infinity, maxE = -Infinity, sumE = 0, sumSqE = 0;
    let minS = Infinity, maxS = -Infinity;
    let maxD = 0, slopeSum = 0;

    statistics.heightHistogram.fill(0);

    const currentTime = performance.now();
    const deltaTime = (currentTime - this.lastAnalysisTime) / 1000 || 0.016;

    for (let i = 0; i < area; i++) {
      const h = heightMap[i];
      const s = sedimentMap[i];
      const b = bedrockMap[i];
      const d = dischargeMap[i];

      totalW += d;
      totalS += s;
      totalB += b;
      sumE += h;
      sumSqE += h * h;

      if (h < minE) minE = h;
      if (h > maxE) maxE = h;
      if (s < minS) minS = s;
      if (s > maxS) maxS = s;
      if (d > maxD) maxD = d;

      if (d > 0.05) riverCells++;

      const bin = Math.min(255, Math.max(0, (h * 255) | 0));
      statistics.heightHistogram[bin]++;

      const x = i % size;
      const y = (i / size) | 0;
      if (x < size - 1 && y < size - 1) {
        const sa = this._calcCellSA(x, y, terrain, heightScale);
        totalSA += sa;
        slopeSum += (sa - 1.0);
      }
    }

    statistics.minElevation = minE;
    statistics.maxElevation = maxE;
    statistics.heightBounds = { min: minE, max: maxE };
    statistics.sedimentBounds = { min: minS, max: maxS };
    statistics.dischargeBounds = { min: 0, max: maxD };
    statistics.peakDischarge = maxD;

    statistics.avgElevation = sumE / area;
    const variance = (sumSqE / area) - (statistics.avgElevation ** 2);
    statistics.elevationStdDev = Math.sqrt(Math.max(0, variance));

    statistics.totalWater = totalW;
    statistics.totalSediment = totalS;
    statistics.totalBedrock = totalB;

    statistics.rugosity = totalSA / area;
    statistics.slopeComplexity = slopeSum / area;
    statistics.drainageDensity = (riverCells / area) * 100;
    statistics.activeWaterCover = riverCells;

    statistics.sedimentFlux = (totalS - this.prevTotalSediment) / deltaTime;
    statistics.erosionRate = (this.prevTotalBedrock - totalB) / deltaTime;
    statistics.hydraulicResidence = totalW / (evaporationRate * area + 1e-6);

    this._normaliseHistogram();

    this.prevTotalSediment = totalS;
    this.prevTotalBedrock = totalB;
    this.lastAnalysisTime = currentTime;
  }

  _normaliseHistogram() {
    const { heightHistogram, normHistogram } = this.m.statistics;
    let maxBin = 0;
    for (let i = 0; i < 256; i++) if (heightHistogram[i] > maxBin) maxBin = heightHistogram[i];
    for (let i = 0; i < 256; i++) normHistogram[i] = maxBin > 0 ? heightHistogram[i] / maxBin : 0;
  }

  _calcCellSA(x, y, terrain, scale) {
    const { size, heightMap } = terrain;
    const i = y * size + x;
    const h00 = heightMap[i] * scale, h10 = heightMap[i+1] * scale;
    const h01 = heightMap[i+size] * scale, h11 = heightMap[i+size+1] * scale;
    const dx = (h10 - h00 + h11 - h01) * 0.5;
    const dy = (h01 - h00 + h11 - h10) * 0.5;
    return Math.sqrt(1 + dx * dx + dy * dy);
  }

  getAverageHeightInRegion(nx, ny, nSize) {
    const { size, heightMap } = this.m.terrain;
    const startX = (nx * size) | 0, startY = (ny * size) | 0, edge = (nSize * size) | 0;
    let sum = 0, count = 0;
    for (let y = startY; y < startY + edge && y < size; y++) {
      for (let x = startX; x < startX + edge && x < size; x++) {
        sum += heightMap[y * size + x];
        count++;
      }
    }
    return count > 0 ? sum / count : 0;
  }

  getHypsometricIntegral(threshold = 0.5) {
    const { heightHistogram } = this.m.statistics;
    const startBin = (threshold * 255) | 0;
    let countAbove = 0;
    for (let i = startBin; i < 256; i++) countAbove += heightHistogram[i];
    return (countAbove / this.m.terrain.area) * 100;
  }
}

// === Tab: Media.js ===
class Media {
  constructor(manager) {
    this.m = manager;

    this.mediaRecorder = null;
    this.recordedChunks = [];
    this.isRecording = false;

    this.importInput = document.createElement("input");
    this.importInput.type = "file";
    this.importInput.accept = "image/*";
    this.importInput.style.display = "none";

    this.importInput.addEventListener("change", (event) => {
      const file = event.target.files[0];
      if (file) this.handleImport(file);
    });

    document.body.appendChild(this.importInput);
  }

  openImportDialog() {
    console.warn("WARNING: This feature is currently unstable.");
    this.importInput.value = "";
    this.importInput.click();
  }

  handleImport(file) {
    if (!file?.type.startsWith("image")) {
      console.error("Import failed: provided file is not an image");
      return;
    }

    const reader = new FileReader();
    reader.onload = (event) => {
      const imgSrc = event.target.result;

      loadImage(imgSrc, (img) => {
        try {
          const { terrain } = this.m;
          const { size, area, heightMap, bedrockMap, originalHeightMap, sedimentMap } = terrain;

          if (!img) throw new Error("loadImage returned null");

          img.resize(size, size);
          img.loadPixels();

          const { pixels } = img;
          if (!pixels || pixels.length < area * 4) throw new Error("pixel buffer incomplete");

          for (let i = 0; i < area; i++) {
            const idx = i << 2;

            const brightness = (
              0.2126 * pixels[idx]     + 
              0.7152 * pixels[idx + 1] + 
              0.0722 * pixels[idx + 2]
            ) / 255;

            heightMap[i] = bedrockMap[i] = originalHeightMap[i] = brightness;
            sedimentMap[i] = 0;
          }

          terrain.reset();
          console.log(`Heightmap imported: ${size}×${size}`);
        } catch (err) {
          console.error("Import failed during processing:", err);
        }
      }, (err) => console.error("Import failed: load error", err));
    };

    reader.readAsDataURL(file);
  }

  startRecording() {
    if (this.isRecording) return;

    const sourceCanvas = _renderer.elt;
    if (!sourceCanvas) return console.error("No valid canvas found");

    this.recordedChunks = [];

    const types = ["video/webm;codecs=vp8", "video/mp4", "video/webm"];
    const supportedType = types.find(t => MediaRecorder.isTypeSupported(t));

    if (!supportedType) return console.error("No supported video format found");

    try {
      const stream = sourceCanvas.captureStream(60);
      this.mediaRecorder = new MediaRecorder(stream, {
        mimeType: supportedType,
        videoBitsPerSecond: 8000000,
      });

      this.mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) this.recordedChunks.push(event.data);
      };

      this.mediaRecorder.onstop = () => {
        const blob = new Blob(this.recordedChunks, { type: supportedType });
        const ext = supportedType.includes("mp4") ? "mp4" : "webm";
        this._triggerDownload(URL.createObjectURL(blob), this._getFilename(ext));
      };

      this.mediaRecorder.start();
      this.isRecording = true;
      console.log(`Recording: ${supportedType}`);
    } catch (err) {
      console.error("Recording failed:", err);
      this.stopRecording();
    }
  }

  stopRecording() {
    if (!this.mediaRecorder || !this.isRecording) return;
    this.mediaRecorder.stop();
    this.isRecording = false;
    this.recordedChunks = [];
  }

  exportImage() {
    const { imageFormat } = this.m.params;
    try {
      const filename = this._getFilename(imageFormat);
      save(_renderer, filename);
      console.log(`Exported: ${filename}`);
    } catch (err) {
      console.error(`Export failed: ${err}`);
    }
  }

  _triggerDownload(url, filename) {
    const anchor = document.createElement("a");
    anchor.style.display = "none";
    anchor.href = url;
    anchor.download = filename;

    document.body.appendChild(anchor);
    anchor.click();

    setTimeout(() => {
      document.body.removeChild(anchor);
      URL.revokeObjectURL(url);
    }, 100);
  }

  _getFilename(extension) {
    const { terrainSize, surfaceMap, displayMethod } = this.m.params;
    const { name, version } = this.m.metadata;
    const ts = Date.now();

    return `${name}_${version}_${displayMethod}_${surfaceMap}_${terrainSize}_${ts}.${extension}`;
  }
}

// === Tab: GUI.js ===
class GUI {
  constructor(manager) {
    this.m = manager;
    const { name, version, author } = this.m.metadata;

    this.pane = new Tweakpane.Pane({
      title: `${name} ${version} by ${author}`,
      expanded: true,
    });

    this.setupTabs();
  }

  setupTabs() {
    const tabs = this.pane.addTab({
      pages: [
        { title: "General" },
        { title: "Erosion" },
        { title: "Visuals" },
        { title: "Media" },
		  { title: "Stats" },
      ],
    });

    const [general, erosion, visuals, media, stats] = tabs.pages;
    this.createGeneralTab(general);
    this.createErosionTab(erosion);
    this.createVisualTab(visuals);
    this.createMediaTab(media);
	 this.createStatsTab(stats);
  }

  createGeneralTab(page) {
    const { params, statistics } = this.m;

    page.addButton({ title: "Generate Terrain" }).on("click", () => this.m.generate());
    page.addButton({ title: "Reset Terrain" }).on("click", () => this.m.reset());
    page.addBlade({ view: "separator" });

    page.addBinding(statistics, "fps", {
      readonly: true,
      label: "FPS",
      view: "graph",
      interval: 60,
      min: 0,
      max: 100,
    });

	 page.addBlade({ view: "separator" });

	 page.addBinding(statistics, "simulationTime", { label: "Simulation Time (s)", readonly: true });

    page.addBlade({ view: "separator" });

    page.addBinding(params, "running", { label: "Running" });
    page.addBinding(params, "dropletsPerFrame", { label: "Droplets/Frame", min: 0, max: 512, step: 1 });
    page.addBinding(params, "maxAge", { label: "Max Age", min: 128, max: 512, step: 1 });
    page.addBinding(params, "minVolume", { label: "Min Volume", min: 0.001, max: 0.1, step: 0.001 });

    const genFolder = page.addFolder({ title: "Generation" });
    genFolder.addBinding(params, "terrainSize", {
      label: "Size",
      options: { "128×128": 128, "256×256": 256, "512×512": 512 },
    });
    genFolder.addBinding(params, "noiseScale", { label: "Scale", min: 0.1, max: 5 });
    genFolder.addBinding(params, "noiseOctaves", { label: "Octaves", min: 1, max: 12, step: 1 });
  }

  createErosionTab(page) {
    const { params } = this.m;
    const hydraulic = page.addFolder({ title: "Hydraulic" });

    const hydraulicSettings = [
      { key: "sedimentErosionRate", label: "Sediment Erosion", min: 0, max: 0.2 },
      { key: "bedrockErosionRate", label: "Bedrock Erosion", min: 0, max: 0.2 },
      { key: "depositionRate", label: "Deposition", min: 0, max: 0.2 },
      { key: "evaporationRate", label: "Evaporation", min: 0.001, max: 1, step: 0.001 },
      { key: "precipitationRate", label: "Precipitation", min: 0, max: 5 },
      { key: "entrainment", label: "Entrainment", min: 0, max: 10 },
      { key: "gravity", label: "Gravity", min: 0.1, max: 5 },
      { key: "momentumTransfer", label: "Momentum Transfer", min: 0, max: 4 },
      { key: "learningRate", label: "Learning Rate", min: 0, max: 0.5 }
    ];

    hydraulicSettings.forEach(s => hydraulic.addBinding(params, s.key, s));

    page.addBlade({ view: "separator" });

    const thermal = page.addFolder({ title: "Thermal" });
    thermal.addBinding(params, "maxHeightDiff", { label: "Max Δ Height", min: 0.01, max: 1 });
    thermal.addBinding(params, "settlingRate", { label: "Settling Rate", min: 0, max: 1 });
  }

  createVisualTab(page) {
    const { params, colourMaps } = this.m;

    page.addBinding(params, "displayMethod", {
      label: "Display Method",
      options: { "3D": "3D", "2D": "2D" },
    });

    page.addBinding(params, "surfaceMap", {
      label: "Surface Map",
      options: {
        "Composite": "composite", "Height Map": "height", "Slope": "slope", 
        "Discharge": "discharge", "Sediment": "sediment", "Delta": "delta", 
       },
    });

	  // need to figure out delta divergent colour map?

    const colourMapOptions = Object.keys(colourMaps).reduce((obj, name) => {
      obj[name.charAt(0).toUpperCase() + name.slice(1)] = name;
      return obj;
    }, {});

    page.addBinding(params, "colourMap", { options: colourMapOptions, label: "Colour Map" });
    page.addBinding(params, "heightScale", { label: "Height Scale", min: 1, max: 256 });

    const overlay = page.addFolder({ title: "Overlay" });
    overlay.addBinding(params, "renderStats", { label: "Stats" });
    overlay.addBinding(params, "renderLegend", { label: "Legend" });

    const light = page.addFolder({ title: "Lighting" });
    light.addBinding(params, "lightDir", {
      label: "Direction",
      x: { min: -100, max: 100 }, y: { min: -100, max: 100 }, z: { min: -100, max: 100 },
    });
    light.addBinding(params, "specularIntensity", { label: "Specular Intensity", min: 0.01, max: 1024 });

    const colours = page.addFolder({ title: "Colour Palette" });
    ["sky", "flat", "steep", "sediment", "water"].forEach(type => {
      colours.addBinding(params, `${type}Colour`, { label: type.charAt(0).toUpperCase() + type.slice(1) });
    });
  }

  createMediaTab(page) {
    const { media, params } = this.m;

    const imp = page.addFolder({ title: "Import" });
    imp.addButton({ title: "Import Heightmap" }).on("click", () => media.openImportDialog());

    const exp = page.addFolder({ title: "Export" });
    const btn = exp.addButton({ title: media.isRecording ? "Stop Recording" : "Start Recording" });

    btn.on("click", () => {
      if (media.isRecording) {
        media.stopRecording();
      } else {
        media.startRecording();
      }

      btn.title = media.isRecording ? "Stop Recording" : "Start Recording";
    });

    exp.addBlade({ view: "separator" });
    exp.addBinding(params, "imageFormat", {
      label: "Format",
      options: { PNG: "png", JPG: "jpg", WebP: "webp" }
    });
    exp.addButton({ title: "Export Image" }).on("click", () => media.exportImage());
  }

  createStatsTab(page) {
    const { statistics } = this.m;

    const perfFolder = page.addFolder({ title: 'Performance & Time' });

    perfFolder.addBinding(statistics, 'fps', {
      readonly: true,
      label: 'FPS',
      view: 'graph',
      interval: 100,
      bufferSize: 60,
      min: 0,
      max: 120,
    });

    perfFolder.addBinding(statistics, 'simulationTime', {
      readonly: true,
      label: 'Simulation Time (s)',
      format: (v) => v.toFixed(1)
    });

    const elevationFolder = page.addFolder({ title: 'Topography' });

    elevationFolder.addBinding(statistics, 'avgElevation', {
      readonly: true,
      label: 'Average Elevation',
